import re
import os
import sys
import pkgutil

MULTIPLE_WHITESPACE_PATTERN = re.compile(r"\s+", re.UNICODE)


def normalize_whitespace(text):
    """
    Translates multiple whitespace into single space character.
    If there is at least one new line character chunk is replaced
    by single LF (Unix new line) character.
    """
    return MULTIPLE_WHITESPACE_PATTERN.sub(_replace_whitespace, text)


def _replace_whitespace(match):
    """Normalize all spacing characters that aren't a newline to a space."""
    text = match.group()
    return "\n" if "\n" in text or "\r" in text else " "


def is_blank(string):
    """
    Returns `True` if string contains only white-space characters
    or is empty. Otherwise `False` is returned.
    """
    return not string or string.isspace()


def _stoplists_path():
    """Returns path to the directory with built-in stop-lists."""
    package = sys.modules.get(__name__.rsplit(".", 1)[0])
    package_file = getattr(package, "__file__", None) or __file__

    return os.path.join(os.path.dirname(os.path.abspath(package_file)), "stoplists")


def get_stoplists():
    """Returns a collection of built-in stop-lists."""
    path_to_stoplists = _stoplists_path()

    stoplist_names = []
    for filename in os.listdir(path_to_stoplists):
        name, extension = os.path.splitext(filename)
        if extension == ".txt":
            stoplist_names.append(name)

    return frozenset(stoplist_names)


def get_stoplist(language):
    """Returns an built-in stop-list for the language as a set of words."""
